const userPrompt = `Rascunho a revisar:\n\n${$json.rascunho}\n\nFatos-base (nao pode contradizer): ${$json.resumo}`;
const systemPrompt = "Voce e um copydesk editorial senior, seguindo o padrao dos 4 Cs de edicao (Clareza, Coerencia, Consistencia, Correcao). Revise o rascunho de post de LinkedIn abaixo nestas dimensoes: (1) Correcao - gramatica e ortografia em portugues do Brasil, e precisao factual (o texto nao pode afirmar nada que nao esteja nos fatos fornecidos), alem de garantir que ha mencao clara a fonte da noticia; (2) Clareza - o leitor precisa entender de primeira, sem ambiguidade; (3) Coerencia - o raciocinio do texto precisa fazer sentido do inicio ao fim, sem saltos logicos; (4) Consistencia - tom de voz de assessor de investimentos experiente, direto, sem jargao excessivo, confiavel, sem sensacionalismo, mantido do inicio ao fim. NAO se preocupe com SEO, hashtags ou gancho de abertura - isso e responsabilidade de outra etapa. NAO junte paragrafos curtos em um paragrafo maior - preserve as quebras de linha e o tamanho dos paragrafos do rascunho original, mesmo ao corrigir o texto dentro deles. NAO introduza transicoes didaticas do tipo 'a licao aqui e', 'isso nos ensina', 'para quem investe, isso significa' - se o rascunho ja evita esse padrao, mantenha evitando. Corrija o texto quando necessario e devolva a versao revisada. Responda SOMENTE em JSON valido, sem markdown, sem crases, no formato exato: {\"post_revisado\": \"...\", \"checklist\": {\"gramatica_ok\": true, \"fontes_citadas\": true, \"clareza_ok\": true, \"coerencia_ok\": true, \"tom_ok\": true}, \"ajustes_feitos\": \"...\"}";
return {
  json: {
    topic: $json.topic,
    articles: $json.articles,
    rascunho: $json.rascunho,
    hashtags_rascunho: $json.hashtags_rascunho,
    requestBody: {
      model: 'deepseek-chat',
      temperature: 0.3,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ]
    }
  }
};

const origin = $('11. Copydesk - Montar Prompt').item.json;
const raw = $json.choices[0].message.content;

let parsed;
try {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    post_revisado: origin.rascunho,
    checklist: { gramatica_ok: false, fontes_citadas: false, clareza_ok: false, coerencia_ok: false, tom_ok: false },
    ajustes_feitos: 'Erro ao interpretar resposta da IA: ' + e.message
  };
}

return {
  json: {
    topic: origin.topic,
    articles: origin.articles,
    post_revisado: parsed.post_revisado,
    hashtags_rascunho: origin.hashtags_rascunho,
    checklist_copydesk: parsed.checklist,
    ajustes_copydesk: parsed.ajustes_feitos
  }
};

const post = $json.post_revisado || '';
const hashtagsBase = ($json.hashtags_rascunho || []).join(', ');

const systemPrompt = `Você é um especialista em growth e distribuição de conteúdo no LinkedIn, atualizado com o algoritmo de 2026. Fato central: o "dwell time" (tempo que a pessoa passa lendo o post) é hoje o principal sinal de qualidade do algoritmo - posts com 0-3s de leitura têm ~1,2% de engajamento, posts com 61s+ têm ~15,6% (13x mais). Hashtags perderam peso algorítmico - o LinkedIn hoje escaneia o TEXTO em busca de palavras-chave de contexto, hashtag não compensa texto fraco.

Sua tarefa, com o post já revisado abaixo:
1. Garanta que as primeiras 1-2 linhas (até ~210 caracteres, antes do corte "ver mais") tenham um gancho forte que prenda atenção e dê vontade de continuar lendo - reescreva a abertura se necessário, sem inventar fatos novos.
2. Garanta que o texto tenha palavras-chave de contexto relevantes ao tema naturalmente incorporadas (não força artificial, apenas garanta que o vocabulário principal do tema apareça no corpo do texto).
3. Estruture em parágrafos curtos e escaneáveis (LinkedIn favorece leitura fácil no mobile).
4. Sugira de 3 a 5 hashtags relevantes e específicas ao tema (nunca genéricas como #investimentos sozinho, combine com termos mais específicos do assunto).

NÃO mude fatos, não adicione informação nova, não mexa no tom já definido pelo copydesk - só otimize estrutura/abertura/hashtags. Responda SOMENTE em JSON válido, sem markdown, sem crases, no formato exato: {"post_final": "...", "hashtags": ["...", "..."], "ajustes_seo": "..."}`;

const userPrompt = `Post revisado pelo copydesk:\n\n${post}\n\nHashtags sugeridas anteriormente (só como referência, pode substituir): ${hashtagsBase}`;

return {
  json: {
    ...$json,
    requestBody: {
      model: 'deepseek-chat',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      temperature: 0.4
    }
  }
  };

const origin = $('12. SEO Growth - Montar Prompt').item.json;
const raw = $json.choices[0].message.content;

let parsed;
try {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    post_final: origin.post_revisado,
    hashtags: origin.hashtags_rascunho || [],
    ajustes_seo: 'Erro ao interpretar resposta da IA: ' + e.message
  };
}

return {
  json: {
    topic: origin.topic,
    articles: origin.articles,
    post_final: parsed.post_final,
    hashtags: (parsed.hashtags || []).join(' '),
    checklist: {
      ...(origin.checklist_copydesk || {}),
      seo_ok: true
    },
    ajustes_feitos: [origin.ajustes_copydesk, parsed.ajustes_seo].filter(Boolean).join(' | ')
  }
};

const fontes = ($json.articles || []).map(a => `${a.source} (${a.url})`).join('; ');
const userPrompt = `Topico: ${$json.topic}\nResumo dos fatos: ${$json.resumo}\nAngulo sugerido: ${$json.angulo_sugerido}\nFontes disponiveis: ${fontes}`;
const systemPrompt = "Voce e um assessor de investimentos escrevendo um post de LinkedIn como se fosse sua propria analise pessoal de um fato do dia - nao como um ghostwriter reportando uma noticia e depois explicando o que ela significa. ESTRUTURA OBRIGATORIA: a primeira frase do post tem que ser em primeira pessoa, estabelecendo que isso e uma leitura/opiniao sua sobre algo que chamou sua atencao - NUNCA comece narrando o fato em terceira pessoa. Exemplos de abertura (nao copie, use so como referencia de tom): 'Uma coisa me chamou atencao essa semana:', 'Prefiro olhar para [tema] com uma pergunta simples:', 'Nao e todo dia que um fato de [setor] me faz repensar [conceito], mas essa semana foi assim:', 'Tem um detalhe nessa noticia que pouca gente comentou, e que pra mim e o mais importante:'. A partir dessa abertura pessoal, o restante do texto continua na MESMA voz - o fato (com fonte citada naturalmente, tipo 'segundo o G1...') entra como evidencia dentro do seu proprio raciocinio, nunca como um bloco de noticia separado que vem antes da opiniao. NUNCA existe uma frase que anuncia a transicao entre fato e analise (tipo 'para quem investe', 'o que isso significa', 'a licao aqui e', 'isso nos ensina') - se voce sente que precisa de uma frase assim pra conectar as duas partes, reescreva o texto inteiro pra nao ter duas partes, e sim uma linha de raciocinio continua desde a primeira frase. Conecte com gestao de risco, decisao sob incerteza e comportamento humano aplicado a investimentos - SEM citar jogos de azar ou qualquer analogia explicita a jogo. Nunca use morte, desastre ou tragedia como gancho. Termine com UMA UNICA reflexao ou pergunta pessoal genuina (nunca duas, nunca generica tipo 'e voce, ja revisou seu portfolio'). Tenha entre 900 e 1300 caracteres. Use paragrafos CURTOS, no maximo 4 a 6 linhas cada, com linha em branco entre eles. Nao invente dados. Responda SOMENTE em JSON valido, sem markdown, sem crases, no formato exato: {\"post\": \"...\", \"hook\": \"...\", \"hashtags\": [\"...\", \"...\"]}";
return {
  json: {
    topic: $json.topic,
    articles: $json.articles,
    resumo: $json.resumo,
    requestBody: {
      model: 'deepseek-chat',
      temperature: 0.5,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ]
    }
  }
};

const origin = $('07. Redator - Montar Prompt').item.json;
let content = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '{}';
content = content.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/, '').trim();
let parsed;
try { parsed = JSON.parse(content); } catch (e) { parsed = { post: '', hook: '', hashtags: [] }; }
return {
  json: {
    topic: origin.topic,
    articles: origin.articles,
    resumo: origin.resumo,
    rascunho: parsed.post || '',
    hook: parsed.hook || '',
    hashtags_rascunho: parsed.hashtags || []
  }
};

const post = $json.post_final || '';
const topic = $json.topic || '';

const systemPrompt = `Você é um estrategista de conteúdo especializado em calls-to-action (CTAs) para LinkedIn, com base no framework de funil de marketing TOFU/MOFU/BOFU e na regra prática de proporção de conteúdo 4:1:1 (a cada 6 posts: 4 de puro valor sem venda, 1 com menção leve, 1 com venda direta).

CONTEXTO IMPORTANTE: este post nasce de um tópico em alta no Google Trends - é conteúdo automatizado de TOPO DE FUNIL (TOFU), alcançando uma audiência fria/mista que não abriu o LinkedIn pensando em contratar um assessor de investimentos. Nessa etapa, CTA de venda ou mesmo convite a contato tende a soar deslocado e cansar quem segue o perfil se aparecer toda hora.

O autor é assessor de investimentos (CVM Resolução 178/2023) e já tem por princípio próprio nunca citar produto/marca específica em conteúdo público, preferindo vender o racional por trás da estratégia. Qualquer CTA usado NÃO PODE: prometer ou insinuar retorno financeiro; recomendar produto ou serviço específico; criar urgência artificial; soar como venda direta não solicitada.

Sua tarefa: ler o post finalizado abaixo e escolher UMA das três opções de fechamento, sendo a primeira a escolha padrão/mais comum:

1. "sem_cta" (escolha padrão, use na GRANDE maioria dos casos): não adicionar nenhum CTA. O post termina com o próprio fechamento que já tem, sem pedir nada ao leitor. cta_texto deve vir como string vazia "".

2. "reflexao_comentario" (use ocasionalmente, quando o tema realmente convida a uma opinião): uma pergunta ou provocação curta que convida o leitor a comentar sua visão/experiência sobre o tema. Não menciona negócio, não convida contato direto.

3. "convite_leve" (use raramente, só quando o tema se conectar de forma muito natural e forte com planejamento financeiro/patrimonial pessoal - não force): um convite suave a trocar uma ideia ou tirar dúvidas em DM/comentário, sem citar produto, sem prazo, sem promessa.

Responda SOMENTE em JSON válido, sem markdown, sem crases, no formato exato: {"cta_tipo": "sem_cta" ou "reflexao_comentario" ou "convite_leve", "cta_texto": "...", "justificativa": "..."}`;

const userPrompt = `Tópico: ${topic}\n\nPost finalizado:\n${post}`;

return {
  json: {
    ...$json,
    requestBody: {
      model: 'deepseek-chat',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      temperature: 0.5
    }
  }
};

const origin = $('13. CTA Estratégico - Montar Prompt').item.json;
const raw = $json.choices[0].message.content;

let parsed;
try {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    cta_tipo: 'sem_cta',
    cta_texto: '',
    justificativa: 'Erro ao interpretar resposta da IA: ' + e.message
  };
}

const postComCta = parsed.cta_texto
  ? `${origin.post_final}\n\n${parsed.cta_texto}`
  : origin.post_final;

return {
  json: {
    topic: origin.topic,
    articles: origin.articles,
    post_final: postComCta,
    hashtags: origin.hashtags,
    checklist: origin.checklist,
    ajustes_feitos: origin.ajustes_feitos,
    cta_tipo: parsed.cta_tipo,
    cta_justificativa: parsed.justificativa
  }
};

const origin = $('15. Guardião da Voz - Montar Prompt').item.json;
const raw = $json.choices[0].message.content;

let parsed;
try {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    post_ajustado: origin.post_final,
    precisou_ajuste: false,
    nota_voz: 'Erro ao interpretar resposta da IA: ' + e.message
  };
}

return {
  json: {
    topic: origin.topic,
    articles: origin.articles,
    post_final: parsed.post_ajustado || origin.post_final,
    hashtags: origin.hashtags,
    checklist: origin.checklist,
    ajustes_feitos: [origin.ajustes_feitos, parsed.nota_voz].filter(Boolean).join(' | '),
    cta_tipo: origin.cta_tipo
  }
};

const post = $json.post_final || '';

const systemPrompt = `Você é o "Guardião da Voz" de o autor, assessor de investimentos de um escritório parceiro de uma corretora. Seu trabalho é revisar o post final e garantir que ele soe genuinamente com a voz dele, não com uma voz corporativa genérica de IA.

Perfil de voz do autor (validado por ele mesmo): é direto e objetivo, vai direto ao ponto - mas directness pra ele NÃO significa ser frio ou seco, existe um jeito certo de falar. Ele é brincalhão, usa muita ironia e MUITA analogia - é seu traço mais forte, usado pra aproximar quem lê e simplificar conceitos difíceis com exemplos do dia a dia. Nunca cita marca ou produto financeiro específico em conteúdo público - prefere falar do racional/estratégia por trás. Sustenta toda afirmação com dado real já apurado, nunca com frase vaga ou promessa de retorno. Gosta de um toque de bastidor/genuíno (nunca inventado) que deixe o conteúdo mais próximo do que institucional.

Revise o post abaixo com esse filtro:
1. Está muito robótico ou genérico, sem nenhuma leveza ou analogia? Se sim, adicione UMA analogia natural e simples que ilustre o ponto central, sem forçar.
2. Está muito frio ou distante? Ajuste o tom pra soar mais próximo, mantendo a objetividade.
3. Tem jargão desnecessário que um leitor comum não entenderia? Simplifique.
4. NÃO mude nenhum fato, dado, fonte, número ou o CTA no final - só ajuste tom e estilo do texto.
5. Se o post já soa alinhado com essa voz, não mexe, devolve exatamente igual.

Responda SOMENTE em JSON válido, sem markdown, sem crases, no formato exato: {"post_ajustado": "...", "precisou_ajuste": true ou false, "nota_voz": "..."}`;

const userPrompt = `Post final a revisar:\n\n${post}`;

return {
  json: {
    ...$json,
    requestBody: {
      model: 'deepseek-chat',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      temperature: 0.4
    }
  }
};
